// SPDX-License-Identifier: MIT
pragma solidity  ^0.8.34;

contract Enquete{
    // Atributos composto
    struct opcaoVoto{
        string descricao;
        uint256 quantidade;
    }

    // Atributos simples
    struct EnqueteInfo{
        string titulo;
        address criador;
        bool activa;
        opcaoVoto[] opcoes;
        mapping(address => bool) jaVotou;
    }  

    mapping(uint256 => EnqueteInfo) private enquetes;
    uint256 private  contadorEnquete;



    // Enquete é criada
    event EnqueteCriada(uint256 idEnquete, string titulo, address criador);
    // Um voto é regitado
    event VotoRegistado(uint256 idEnquete, uint256 indiceOpcao, address votante);
    // Enquete é finalizada
    event EnqueteEncerrada(uint256 idEnquete, address criador);

    function criarEnquete(string memory _titulo, string[] memory _opcoes) external {
        require(_opcoes.length >= 2 && _opcoes.length <= 10, unicode"Deve-se definir, no minimo 2 e maximo 10pelo menos 2 opções");
        contadorEnquete++;
        EnqueteInfo storage novaEnquete = enquetes[contadorEnquete];
        novaEnquete.titulo = _titulo;
        novaEnquete.criador = msg.sender;
        novaEnquete.activa = true;  

        for(uint256 i = 0; i < _opcoes.length; i++){
            novaEnquete.opcoes.push(opcaoVoto({descricao: _opcoes[i], quantidade:0}));
        }

        emit EnqueteCriada(contadorEnquete, _titulo, msg.sender);

    }

    function votar(uint256 _idEnquete, uint256 _indiceOpcao) external {
        EnqueteInfo storage enquete = enquetes[_idEnquete];
        require(enquete.activa, unicode"Enquete não está activa");
        require(enquete.criador != msg.sender, unicode"Não pode votar na sua propria enquete");
        require(_indiceOpcao < enquete.opcoes.length, unicode"Opção invalida");
        require(!enquete.jaVotou[msg.sender], unicode"Já votaste nesta enquete");

            enquete.opcoes[_indiceOpcao].quantidade++;
            enquete.jaVotou[msg.sender] = true;
            emit VotoRegistado(_idEnquete, _indiceOpcao, msg.sender);

  }

    function fecharEnquete(uint256 _idEnquete) external {
        EnqueteInfo storage enquete = enquetes[_idEnquete];
        require(enquete.activa, unicode"Enquete já está fechada");
        require(enquete.criador == msg.sender, unicode"Não és o criador");


        enquete.activa = false;

        emit EnqueteEncerrada(_idEnquete, msg.sender);

    }  

    function getEnquete(uint256 _idEnquete) external view returns (
    string memory titulo,
    bool activa,
    string[] memory nomesOpcoes,
    uint256[] memory votosOpcoes,
    address criador
) {
    EnqueteInfo storage enquete = enquetes[_idEnquete];
    uint256 totalOpcoes = enquete.opcoes.length;

    nomesOpcoes = new string[](totalOpcoes);
    votosOpcoes = new uint256[](totalOpcoes);

    for(uint256 i = 0; i < totalOpcoes; i++) {
        nomesOpcoes[i] = enquete.opcoes[i].descricao;
        votosOpcoes[i] = enquete.opcoes[i].quantidade;
    }

    return (enquete.titulo, enquete.activa, nomesOpcoes, votosOpcoes, enquete.criador);
}
}

contracts/spamNumber.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract SpamNumber {
    address public owner;

    struct Node {
        uint256 reputation;
        bool isBlocked;
    }

    mapping(string => bool) private spamList;
    mapping(address => mapping(address => uint256)) public reputation; // Rij: visão do nó i sobre o vizinho j
    mapping(address => Node) public nodes;
    mapping(address => uint256) public rewards;

    event SpamDetected(string number, address reportedBy);
    event ReputationUpdated(address indexed nodeI, address indexed nodeJ, uint256 newReputation);
    event NodeBlocked(address indexed node);

    modifier onlyOwner() {
        require(msg.sender == owner, "Apenas o proprietario pode executar isto");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    // 1 - Função Verificar: Verifica se o número é spam
    function verificar(string memory _numero) public view returns (bool) {
        return spamList[_numero];
    }

    // 2 - Função Reputação: O nó i atualiza a reputação do vizinho j
    // A probabilidade de verificar uma transação deve ser tratada no front-end/lógica do nó com base neste valor
    function atualizarReputacao(address _vizinho, uint256 _valorComportamento) public {
        // Lógica simples: aumenta ou diminui com base no comportamento (0 a 100)
        reputation[msg.sender][_vizinho] = _valorComportamento;

        emit ReputationUpdated(msg.sender, _vizinho, _valorComportamento);
    }

    // 3 - Função Incentivo: Atribui recompensas para manter a reputação alta
    // Nós que verificam corretamente ganham "pontos" de incentivo
    function incentivo(address _verificador, string memory _numero, bool _confirmadoSpam) public onlyOwner {
        if (_confirmadoSpam) {
            spamList[_numero] = true;
            rewards[_verificador] += 10; // Recompensa por verificação correta
            nodes[_verificador].reputation += 5;
        } else {
            // Penalidade por falso positivo
            nodes[_verificador].reputation = nodes[_verificador].reputation > 10 ? nodes[_verificador].reputation - 10 : 0;
        }
    }

    // 4 - Função Bloqueio: Bloqueia transações/nós antes de chegarem aos mineradores
    function bloqueio(address _usuarioMalicioso) public {
        // Se a reputação cair abaixo de um limite, o nó é bloqueado
        require(nodes[_usuarioMalicioso].reputation < 20, "Reputacao ainda aceitavel");

        nodes[_usuarioMalicioso].isBlocked = true;
        emit NodeBlocked(_usuarioMalicioso);
    }

    // Função para reportar um número (alimenta o sistema)
    function reportarSpam(string memory _numero) public {
        require(!nodes[msg.sender].isBlocked, "O seu no esta bloqueado");
        emit SpamDetected(_numero, msg.sender);
    }
}
